sys_script_include.script:
var BudgetUtilsClient = Class.create();
BudgetUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    approveBudget: function() {
        var budgetId = this.getParameter('sysparm_budgetId');

        var gr = new GlideRecord('x_1790229_event_ma_budget');
        if (gr.get(budgetId)) {
            gr.u_status = 'approve';
            gr.update();


            return 'success';
        }
        return 'failure';
    },

    type: 'TaskUtilsClient'
});
